                f"as the first column{plural} but time series has no columns"
            )

        elif self.colnames[:len(required_columns)] != required_columns:

            missing = [col for col in required_columns if col not in self.colnames]
            if missing:
                raise ValueError(
                    f"{self.__class__.__name__} object is invalid - expected {required_columns} "
                    f"as the first column{plural} but found {self.colnames[:len(required_columns)]}"
                )
            else:
                raise ValueError(
                    f"{self.__class__.__name__} object is invalid - expected '{required_columns[0]}' "
                    f"as the first column{plural} but found '{self.colnames[0]}'"
                )
